import json
from itertools import permutations

def solve_puzzle():
    # Input variables (puzzle parameters)
    houses = [1, 2]  # numbered left (1) to right (2)
    attributes = {
        "Name": ["Eric", "Arnold"],
        "Lunch": ["pizza", "grilled cheese"],
    }

    # Generate all permutations for each attribute to enforce all-different
    name_perms = list(permutations(attributes["Name"]))
    lunch_perms = list(permutations(attributes["Lunch"]))

    solutions = []

    for name_assignment in name_perms:
        for lunch_assignment in lunch_perms:
            # Build assignment by house
            assignment = {}
            for idx, h in enumerate(houses):
                assignment[h] = {
                    "Name": name_assignment[idx],
                    "Lunch": lunch_assignment[idx],
                }

            # Apply clues:
            # 1. The person who is a pizza lover is in the second house.
            if assignment[2]["Lunch"] != "pizza":
                continue

            # 2. Arnold is not in the first house.
            if assignment[1]["Name"] == "Arnold":
                continue

            solutions.append(assignment)

    if len(solutions) != 1:
        raise ValueError(f"Expected a unique solution, found {len(solutions)}.")

    solution = solutions[0]

    # Prepare JSON output
    header = ["House", "Name", "Lunch"]
    rows = []
    for h in houses:
        rows.append([str(h), solution[h]["Name"], solution[h]["Lunch"]])

    return {
        "solution": {
            "header": header,
            "rows": rows
        }
    }

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False, indent=2))
